mkdir -p <LOCAL_PATH>/.ror-eval-state/fakeuser
cat > <LOCAL_PATH>/.ror-eval-state/fakeuser/fakeuser.c <<'EOF'
#define _GNU_SOURCE
#include <pwd.h>
#include <grp.h>
#include <string.h>
#include <unistd.h>
#include <stdlib.h>

static struct passwd fake_pw;
static char name_buf[] = "postgres";
static char dir_buf[4096];
static char shell_buf[] = "/bin/bash";
static char gecos_buf[] = "postgres";
static int initialized = 0;

static void init_fake(void) {
    if (initialized) return;
    const char *home = getenv("HOME");
    if (!home) home = "/tmp";
    strncpy(dir_buf, home, sizeof(dir_buf) - 1);
    fake_pw.pw_name = name_buf;
    fake_pw.pw_passwd = "";
    fake_pw.pw_uid = getuid();
    fake_pw.pw_gid = getgid();
    fake_pw.pw_gecos = gecos_buf;
    fake_pw.pw_dir = dir_buf;
    fake_pw.pw_shell = shell_buf;
    initialized = 1;
}

struct passwd *getpwuid(uid_t uid) {
    init_fake();
    return &fake_pw;
}

int getpwuid_r(uid_t uid, struct passwd *pwd, char *buf, size_t buflen, struct passwd **result) {
    init_fake();
    *pwd = fake_pw;
    if (result) *result = pwd;
    return 0;
}

struct passwd *getpwnam(const char *name) {
    init_fake();
    return &fake_pw;
}

int getpwnam_r(const char *name, struct passwd *pwd, char *buf, size_t buflen, struct passwd **result) {
    init_fake();
    *pwd = fake_pw;
    if (result) *result = pwd;
    return 0;
}
EOF
gcc -shared -fPIC -o <LOCAL_PATH>/.ror-eval-state/fakeuser/libfakeuser.so <LOCAL_PATH>/.ror-eval-state/fakeuser/fakeuser.c
ls -la <LOCAL_PATH>/.ror-eval-state/fakeuser/

